for tid, info in DATA.items():
    sk = os.path.join(TASK, tid + ".json")
    d = json.load(open(sk, encoding="utf-8"))
    n = len(d["translations"])
    assert n == len(info["moderns"]), f"{tid} 段数不符 {n} vs {len(info['moderns'])}"
    for s, m in zip(d["translations"], info["moderns"]):
        s["modern"] = m
    d["mode"] = "白话"
    d["intro"] = info["intro"]
    if tid == "t1977":
        d["translator"] = "明 袾宏撰"
    json.dump(d, open(os.path.join(OUT, tid + ".json"), "w", encoding="utf-8"),
              ensure_ascii=False, indent=1)
    print("写出", tid, n, "段")

print("完成")
